css:
html,body{margin:0;padding:0;height:100%}
.ecw-desk{display:flex;flex-direction:column;height:100%;overflow:hidden;background:#e1dede;font:12px 'DejaVu Sans',Verdana,Arial,Helvetica,sans-serif;color:#000;box-sizing:border-box}
.ecw-desk *{box-sizing:border-box}
.ecw-topbar{flex:none;height:29px;display:flex;align-items:center;justify-content:flex-end;background-image:linear-gradient(#ffffff,#efefef 50%);box-shadow:0 0 3px -1px #000;font-family:'DejaVu Sans',Verdana,Arial,Helvetica,sans-serif;position:relative;z-index:2}
.ecw-topbar-item{display:block;height:25px;margin:0 5px}
.ecw-user{font-size:14px;line-height:28px;color:#426c8c;margin:0 0 0 5px;height:auto}
.ecw-window{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;margin:0;border-left:3px solid #4a789c;border-right:3px solid #4a789c;border-bottom:3px solid #4a789c;border-radius:3px;box-shadow:0 0 5px 0 #000;font-family:'DejaVu Sans',Verdana,Arial,Helvetica,sans-serif;background:#4a789c}
.ecw-title{flex:none;position:relative;height:28px;display:flex;align-items:flex-start;background:#4a789c;border-bottom:1px solid #333333;margin:0 -3px;padding:0 3px;border-top-left-radius:3px;border-top-right-radius:3px}
.ecw-icon{display:block;width:25px;height:21px;margin-top:3px;background:url(data:image/png;base64,) center center no-repeat}
.ecw-title-text{display:block;margin-top:2px;line-height:25px;font-size:14px;color:#ffffff;white-space:nowrap;font-family:'DejaVu Sans',Verdana,Arial,Helvetica,sans-serif}
.ecw-buttons{position:absolute;right:0;top:1px;height:25px;padding-right:3px;display:flex}
.ecw-btn{position:relative;display:block;width:23px;height:25px}
.ecw-btn img{position:absolute;top:0;right:0;bottom:0;left:0;margin:auto;width:20px;height:20px}
.ecw-btn-set img{width:17px;height:18px}
.ecw-body{flex:1 1 auto;min-height:0;background:#e1dede;overflow:auto;margin:0 -3px;padding:20px 3px 0;font:12px Arial,Helvetica,sans-serif;color:#000}
.ecw-fieldset{display:block;width:fit-content;min-width:460px;min-height:96px;max-width:100%;margin:0 auto;padding:4px 9px 8px;border:2px groove #efefef;font:12px Arial,Helvetica,sans-serif;color:#000}
.ecw-legend{padding:0 2px;font:bold 12px Arial,Helvetica,sans-serif;color:#000}
.ecw-status{flex:none;height:20px;margin:0 -3px;padding:0 5px 0 10px;position:relative;display:flex;align-items:center;justify-content:space-between;background:#dddddd;color:#545454;font:12px/20px Arial,Helvetica,sans-serif;white-space:nowrap}
.ecw-status-l,.ecw-status-r{display:flex;align-items:center}
.ecw-status-l span{margin-right:20px}
.ecw-status-r span{margin-left:5px}
.ecw-status b{color:#000}
.ecw-taskbar{flex:none;height:36px;display:flex;align-items:stretch;position:relative;background:#4a789c;box-shadow:0 1px 5px 0 #000;font-family:'DejaVu Sans',Verdana,Arial,Helvetica,sans-serif;z-index:2}
.ecw-menu{width:100px;height:36px;background:#426c8c;color:#fdfdfd;text-align:center;font-size:14px;line-height:36px}
.ecw-tab{position:relative;height:36px;min-width:150px;padding:0 10px;background:#2c5676;color:#fdfdfd;text-align:center;font-size:11px;line-height:36px;white-space:nowrap}
.ecw-tab:after{content:"";position:absolute;left:100%;top:0;bottom:0;height:24px;margin:auto 0 auto 2px;border-right:1px solid #426c8c}
.ecw-list{position:absolute;right:0;top:0;width:40px;height:36px;background:#4a789c;padding:10px 9px 6px 11px}
.ecw-list span{display:block;width:20px;height:4px;margin-bottom:3px;border-radius:1px;background:#ededed}
